    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&family=Tajawal:wght@400;500;700&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#22232c;--rose:#a85e78;--rose-dark:#87465f;--line:#eadfe1;--muted:#777985}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 15% 15%,#f8e3e6 0,transparent 30%),radial-gradient(circle at 87% 90%,#d9e5e1 0,transparent 30%),#fcfaf9;color:var(--ink);font:14px 'DM Sans','Tajawal',sans-serif}.layout{width:min(1000px,calc(100% - 40px));min-height:610px;display:grid;grid-template-columns:1.08fr .92fr;background:white;border:1px solid #f0e9e9;border-radius:23px;overflow:hidden;box-shadow:0 24px 70px #4e33421a}.welcome{padding:55px;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#293a47,#405767);color:white}.brand{display:flex;align-items:center;gap:11px}.mark{width:39px;height:39px;display:grid;place-items:center;border-radius:13px;background:linear-gradient(145deg,#c98199,#98536c);font:20px Georgia;box-shadow:0 8px 18px #0002}.brand b{font:700 21px 'Playfair Display',serif}.brand small{display:block;color:#ced7db;font-size:10px;letter-spacing:1.1px;text-transform:uppercase}.welcome h1{font:700 clamp(31px,4vw,45px)/1.12 'Playfair Display',serif;margin:0;max-width:420px;letter-spacing:-1px}.welcome p{color:#d7e0e3;line-height:1.7;max-width:345px}.companies{display:flex;gap:9px;flex-wrap:wrap}.companies span{border:1px solid #ffffff2b;border-radius:14px;padding:7px 10px;color:#dfe5e7;font-size:11px}.form-area{padding:54px;display:flex;flex-direction:column;justify-content:center}.language{align-self:flex-end;color:var(--rose-dark);background:#fdf5f6;border:0;border-radius:8px;padding:8px 11px;font:inherit}.form-area h2{font:700 28px 'Playfair Display',serif;margin:32px 0 7px}.intro{color:var(--muted);margin:0 0 26px}.field{display:block;margin:16px 0}.field span{font-weight:600;font-size:12px;display:block;margin-bottom:7px}.field input{width:100%;border:1px solid var(--line);border-radius:9px;padding:12px 13px;font:inherit;color:var(--ink);outline:none}.field input:focus{border-color:#b9798f;box-shadow:0 0 0 3px #f7e9ed}.error{display:block;margin-top:6px;color:#b03d55;font-size:12px}.remember{display:flex;gap:8px;align-items:center;color:var(--muted);font-size:12px;margin:19px 0 23px}.submit{border:0;border-radius:10px;background:linear-gradient(110deg,#a75b75,#874760);color:white;padding:13px 16px;font:600 14px inherit;cursor:pointer;box-shadow:0 8px 18px #a75b7530}.note{text-align:center;color:#9a9aa2;font-size:11px;line-height:1.6;margin:24px 0 0}@media(max-width:700px){.layout{grid-template-columns:1fr;min-height:auto}.welcome{padding:32px;gap:38px}.welcome h1{font-size:31px}.form-area{padding:36px 30px}.form-area h2{margin-top:20px}}
    </style>
</head>
<body>
<div class="layout">
    <section class="welcome"><div class="brand"><div class="mark">R</div><div><b>Riwaq</b><small>Real estate ERP</small></div></div><div><h1>One calm place for every important move.</h1><p>Manage your group’s marketing, valuations, properties, sales, rentals, and client conversations with clarity.</p></div><div class="companies"><span>Meyar Valuation</span><span>Marsous Marketing</span><span>Al Ramz Realty</span></div></section>
    <main class="form-area"><button class="language" type="button">العربية</button><h2>Welcome back</h2><p class="intro">Sign in with your work email to continue.</p><form method="POST" action="{{ route('login.store') }}">@csrf<div class="field"><label for="email"><span>Work email</span><input id="email" name="email" type="email" value="{{ old('email') }}" autocomplete="email" required autofocus></label>@error('email')<span class="error">{{ $message }}</span>@enderror</div><div class="field"><label for="password"><span>Password</span><input id="password" name="password" type="password" autocomplete="current-password" required></label></div><label class="remember"><input type="checkbox" name="remember" value="1"> Keep me signed in on this device</label><button class="submit" type="submit">Sign in securely →</button></form><p class="note">Your access is protected and managed by your company administrator.</p></main>
</div>
</body>
</html>
